Ext.define('BNK.view.HumanResource.hwm.HwmVctAply01MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.HwmVctAply01MViewController',

    config: {
        viewId: 'HwmVctAply01M'
    },

    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            store = vm.storeInfo.VctStore,
            startDate = DateUtils.getDate(refs.startDate.getValue()),
            endDate = DateUtils.getDate(refs.endDate.getValue()),
            params = {
                startDate : startDate,
                endDate : endDate
            };

        if(startDate > endDate){
            Ext.Msg.alert('확인','시작일이 종료일보다 클 수 없습니다.');
            return false;
        }

        store.getProxy().extraParams = params;
        store.removeAll();
        store.loadPage(1);

    },

    defaut: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            store = vm.storeInfo.Store;

        store.getProxy().extraParams.page = 1;
        var toolbar = refs.grid.getPlugins()[0];
        toolbar.setCurrentPage(1);


    },

    onBtnSearch: function(button, e, eOpts) {
        this.onSelect();
    },

    /* 휴가 신청 버튼 탭 이벤트 : 상세 신청 페이지로 이동 */
    onVacation: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var naviView = me.getView().up('navigationview');
        me.PUSH_VIEW(naviView, {
            menuId  : 'HwmVctAply04M',
            title   : '휴가 신청',
            parentView : me.getView(),
            isSubView : true,
            //     records : records
        });

    },

    /* row 탭으로 신청한 휴가 내역 보기 */
    onGridSelect: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            record = selected[0].data;

        record.beforePage = 'HwmVctAply01M';

        /* window - HwmVctAply71M 화면은 window를 상속받으므로 네비게이션뷰를 사용할 수 없다
        var win = Ext.create('HwmVctAply71M', {
        command : 94,
        aprHistId : record.comAprHistId,
        vctRecord : record
        });
        me.mon(win, 'complete', function(popup) {
        popup.close(); //팝업창닫기
        me.onSelect();
        }, me);
        win.show();
        /* window */


        // 결재이력데이터조회
        Ext.Ajax.request({
            headers : {
                serviceId : 'COMAPR0001R04M',
                viewId : 'HwmVctAply01M'
            },
            scope : me,
            jsonData : {
                aprHistId : record.comAprHistId // 결재이력아이디
            },
            success : function(response) {
                var responseJson = Ext.JSON.decode(Ext.JSON.decode(response.responseText).result);
                if (!responseJson) {
                    return;
                }

                vm.set('responseJson', responseJson);

                var docData = responseJson.docData;
                if (!docData) {
                    docData = {};
                    if (responseJson.fieldValues)  docData.fieldValues  = responseJson.fieldValues;
                    if (responseJson.afterchange)  docData.afterchange  = responseJson.afterchange;
                    if (responseJson.beforechange) docData.beforechange = responseJson.beforechange;
                }

                /* container */
                var naviView = me.getView().up('navigationview');
                me.PUSH_VIEW(naviView, {
                    menuId : 'HwmVctAply05M',
                    title  : '휴가 신청',
                    parentView : me.getView(),
                    isSubView : true,
                    vctRecord : record,
                    docData : docData,
                    afterchange : docData.afterchange
                });
                /* container */
            }
        });




    },

    /* 화면초기화 */
    initialize: function(component, eOpts) {
        var me = this,
            refs = me.getReferences(),
            grid = refs.grid;

        var dateMinus1 = new Date();
        dateMinus1.setDate(1);
        refs.startDate.setValue(DateUtils.parseDate(dateMinus1));

        dateMinus1.setMonth(dateMinus1.getMonth()+1);
        dateMinus1.setDate(7);
        refs.endDate.setValue(DateUtils.parseDate(dateMinus1));

        grid.el.select('.x-headercontainer').setStyle('height',	'0px');

        // grid SELECT
        me.onSelect();

    },

    /* 페이징 등 스토어가 새로 load 될때 동작하는 이벤트 */
    onJsonstoreLoad: function(store, records, successful, operation, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.grid;

    }

});